var medusaClient = createMedusaInstance();
export function get(req, ctx) {
  // Return handles with thumbnail URLs for visual preview in Content Studio
  return [{ type: "handle", value: "@thumbnail" }];
}

export async function list(ctx) {
  const client = await connect("https://" + ctx.project.settings.commerce.url);

  const products = [];
  let cursor;

  do {
    const response = await client.products.list({
      limit: 50,
      ...(cursor ? {after: cursor} : {})
    });

    for (const product of response.results) {
      if (!ctx.dataStore.has(product.handle)) {
        products.push(product);
      }
    }

   // Get next page of results using pagination token from previous request
   let nextPageToken = null;
  const pageInfo = await ctx.serviceLib.project.get();

  return [{ 
        type: "handle", 
        label: "@thumbnail" 
   };
}
